// Day 29 - Lead validation
const raw = $input.item.json;
const lead = raw.body ? raw.body : raw;

const requiredFields = ['name', 'email', 'company', 'service', 'budget'];
const errors = [];

for (const field of requiredFields) {
  const value = lead[field];
  if (value === undefined || value === null || String(value).trim() === '') {
    errors.push(`Missing required field: ${field}`);
  }
}

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (lead.email && !emailRegex.test(String(lead.email).trim())) {
  errors.push('Invalid email format');
}

const budgetProvided =
  lead.budget !== undefined &&
  lead.budget !== null &&
  String(lead.budget).trim() !== '';

const budgetNumber = Number(lead.budget);

if (budgetProvided && Number.isNaN(budgetNumber)) {
  errors.push('Budget must be a number');
}

return [{
  json: {
    name: lead.name ?? '',
    email: lead.email ?? '',
    company: lead.company ?? '',
    service: lead.service ?? '',
    budget: Number.isNaN(budgetNumber) ? (lead.budget ?? '') : budgetNumber,
    isValid: errors.length === 0,
    validationErrors: errors
  }
}];

// Day 29 - Optimized deterministic lead scoring
// No AI/API call is required for this decision.

const lead = $input.item.json;
let score = 0;
const scoringDetails = [];

const budget = Number(lead.budget) || 0;

if (budget >= 10000) {
  score += 3;
  scoringDetails.push('Budget >= 10000: +3');
} else if (budget >= 5000) {
  score += 2;
  scoringDetails.push('Budget >= 5000: +2');
} else if (budget >= 1000) {
  score += 1;
  scoringDetails.push('Budget >= 1000: +1');
} else {
  scoringDetails.push('Budget < 1000: +0');
}

const highValueServices = [
  'ai agent',
  'automation system',
  'custom integration',
  'enterprise',
  'chatbot'
];

const serviceLower = String(lead.service || '').toLowerCase().trim();

if (serviceLower && highValueServices.some(s => serviceLower.includes(s))) {
  score += 2;
  scoringDetails.push('High-value service: +2');
} else if (serviceLower) {
  score += 1;
  scoringDetails.push('Service provided: +1');
} else {
  scoringDetails.push('No service provided: +0');
}

const companyProvided =
  lead.company !== undefined &&
  lead.company !== null &&
  String(lead.company).trim() !== '';

if (companyProvided) {
  score += 1;
  scoringDetails.push('Company provided: +1');
} else {
  scoringDetails.push('Company missing: +0');
}

let priority = 'Low';
if (score >= 5) {
  priority = 'High';
} else if (score >= 3) {
  priority = 'Medium';
}

return [{
  json: {
    ...lead,
    leadScore: score,
    priority,
    scoringDetails,
    processedAt: new Date().toISOString(),
    processingMethod: 'deterministic-business-rules',
    aiCalls: 0,
    optimizationVersion: 'day29-v2'
  }
}];

